create extension if not exists citext;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,username citext unique check(username is null or username ~ '^[A-Za-z0-9_]{3,20}$'),display_name text,avatar_url text,username_changed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security;
create policy "profiles are publicly readable" on public.profiles for select using (true);
create policy "users create own profile" on public.profiles for insert to authenticated with check ((select auth.uid())=id);
create policy "users update own profile" on public.profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create or replace function public.create_social_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),coalesce(new.raw_user_meta_data->>'avatar_url',new.raw_user_meta_data->>'picture')) on conflict(id) do nothing;return new;end $$;
drop trigger if exists create_profile_after_signup on auth.users;create trigger create_profile_after_signup after insert on auth.users for each row execute function public.create_social_profile();
insert into public.profiles(id,display_name,avatar_url) select id,coalesce(raw_user_meta_data->>'full_name',raw_user_meta_data->>'name'),coalesce(raw_user_meta_data->>'avatar_url',raw_user_meta_data->>'picture') from auth.users on conflict(id) do nothing;
create or replace function public.enforce_username_cooldown() returns trigger language plpgsql set search_path=public as $$ begin if old.username is distinct from new.username then if old.username is not null and old.username_changed_at is not null and old.username_changed_at>now()-interval '6 months' then raise exception 'username_change_cooldown';end if;new.username_changed_at=now();end if;return new;end $$;
drop trigger if exists enforce_username_cooldown on public.profiles;create trigger enforce_username_cooldown before update on public.profiles for each row execute function public.enforce_username_cooldown();
drop trigger if exists set_updated_at on public.profiles;create trigger set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create table if not exists public.game_saves(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,game_key text not null,name text not null check(char_length(name) between 1 and 50),game_state jsonb not null,summary jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists game_saves_user_idx on public.game_saves(user_id,game_key,created_at);alter table public.game_saves enable row level security;
create policy "users read own game saves" on public.game_saves for select to authenticated using ((select auth.uid())=user_id);
create policy "users create own game saves" on public.game_saves for insert to authenticated with check ((select auth.uid())=user_id);
create policy "users delete own game saves" on public.game_saves for delete to authenticated using ((select auth.uid())=user_id);
create or replace function public.keep_two_career_saves() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.game_key='career' and (select count(*) from public.game_saves where user_id=new.user_id and game_key='career')>=2 then delete from public.game_saves where id=(select id from public.game_saves where user_id=new.user_id and game_key='career' order by created_at asc limit 1);end if;return new;end $$;
drop trigger if exists keep_two_career_saves on public.game_saves;create trigger keep_two_career_saves before insert on public.game_saves for each row execute function public.keep_two_career_saves();
